CREATE TABLE workflow_definitions(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,digest TEXT NOT NULL,name TEXT NOT NULL,version TEXT NOT NULL,definition_json TEXT NOT NULL CHECK(octet_length(definition_json)<=1048576),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,digest),UNIQUE(organization_id,tenant_id,project_id,agent_uid,name,version));
CREATE TABLE workflow_instances(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,id TEXT NOT NULL,task_id TEXT NOT NULL,definition_digest TEXT NOT NULL,status TEXT NOT NULL,revision BIGINT NOT NULL,instance_json TEXT NOT NULL CHECK(octet_length(instance_json)<=131072),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,id),UNIQUE(organization_id,tenant_id,project_id,agent_uid,task_id));
CREATE TABLE workflow_nodes(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,instance_id TEXT NOT NULL,node_id TEXT NOT NULL,occurrence BIGINT NOT NULL,revision BIGINT NOT NULL,state TEXT NOT NULL,node_json TEXT NOT NULL CHECK(octet_length(node_json)<=16384),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,instance_id,node_id,occurrence));
CREATE TABLE workflow_leases(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,instance_id TEXT NOT NULL,node_id TEXT NOT NULL,occurrence BIGINT NOT NULL,epoch BIGINT NOT NULL,executor_id TEXT NOT NULL,expires_at_ms BIGINT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,instance_id,node_id,occurrence));
CREATE TABLE workflow_events(cursor BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,instance_id TEXT NOT NULL,event_json TEXT NOT NULL CHECK(octet_length(event_json)<=4096));
CREATE TABLE workflow_operations(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,actor_id TEXT NOT NULL,operation_id TEXT NOT NULL,command_digest TEXT NOT NULL,result_json TEXT NOT NULL CHECK(octet_length(result_json)<=1048576),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,actor_id,operation_id));
ALTER TABLE workflow_definitions ENABLE ROW LEVEL SECURITY; ALTER TABLE workflow_definitions FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_scope ON workflow_definitions USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
ALTER TABLE workflow_instances ENABLE ROW LEVEL SECURITY; ALTER TABLE workflow_instances FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_scope ON workflow_instances USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
ALTER TABLE workflow_nodes ENABLE ROW LEVEL SECURITY; ALTER TABLE workflow_nodes FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_scope ON workflow_nodes USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
ALTER TABLE workflow_leases ENABLE ROW LEVEL SECURITY; ALTER TABLE workflow_leases FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_scope ON workflow_leases USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
ALTER TABLE workflow_events ENABLE ROW LEVEL SECURITY; ALTER TABLE workflow_events FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_scope ON workflow_events USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
ALTER TABLE workflow_operations ENABLE ROW LEVEL SECURITY; ALTER TABLE workflow_operations FORCE ROW LEVEL SECURITY; CREATE POLICY tenant_scope ON workflow_operations USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
CREATE TRIGGER immutable_workflow_definitions BEFORE UPDATE OR DELETE ON workflow_definitions FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
CREATE TRIGGER immutable_workflow_events BEFORE UPDATE OR DELETE ON workflow_events FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
CREATE TRIGGER immutable_workflow_operations BEFORE UPDATE OR DELETE ON workflow_operations FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();

CREATE FUNCTION workflow_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
IF ROW(NEW.organization_id,NEW.tenant_id,NEW.project_id,NEW.agent_uid) IS DISTINCT FROM ROW(OLD.organization_id,OLD.tenant_id,OLD.project_id,OLD.agent_uid) THEN RAISE EXCEPTION 'immutable workflow scope'; END IF;
IF TG_TABLE_NAME='workflow_instances' THEN
 IF ROW(NEW.id,NEW.task_id,NEW.definition_digest) IS DISTINCT FROM ROW(OLD.id,OLD.task_id,OLD.definition_digest) OR NEW.instance_json::jsonb->'input_digest' IS DISTINCT FROM OLD.instance_json::jsonb->'input_digest' OR NEW.instance_json::jsonb->'creator' IS DISTINCT FROM OLD.instance_json::jsonb->'creator' OR NEW.revision<=OLD.revision THEN RAISE EXCEPTION 'immutable workflow identity'; END IF;
ELSIF TG_TABLE_NAME='workflow_nodes' THEN
 IF ROW(NEW.instance_id,NEW.node_id,NEW.occurrence) IS DISTINCT FROM ROW(OLD.instance_id,OLD.node_id,OLD.occurrence) OR NEW.node_json::jsonb->'input_digest' IS DISTINCT FROM OLD.node_json::jsonb->'input_digest' OR CAST(NEW.node_json::jsonb->>'lease_epoch' AS BIGINT)<CAST(OLD.node_json::jsonb->>'lease_epoch' AS BIGINT) OR NEW.revision<=OLD.revision THEN RAISE EXCEPTION 'immutable node input or stale fence'; END IF;
ELSE
 IF NEW.epoch<OLD.epoch OR (NEW.epoch=OLD.epoch AND NEW.executor_id<>OLD.executor_id) THEN RAISE EXCEPTION 'stale workflow lease'; END IF;
END IF; RETURN NEW; END $$;
CREATE TRIGGER workflow_instance_identity BEFORE UPDATE ON workflow_instances FOR EACH ROW EXECUTE FUNCTION workflow_identity_guard();
CREATE TRIGGER workflow_node_identity BEFORE UPDATE ON workflow_nodes FOR EACH ROW EXECUTE FUNCTION workflow_identity_guard();
CREATE TRIGGER workflow_lease_epoch BEFORE UPDATE ON workflow_leases FOR EACH ROW EXECUTE FUNCTION workflow_identity_guard();
CREATE TRIGGER immutable_workflow_instance_delete BEFORE DELETE ON workflow_instances FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
CREATE TRIGGER immutable_workflow_node_delete BEFORE DELETE ON workflow_nodes FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
INSERT INTO principals SELECT organization_id,tenant_id,'local-workflow-workload','workload',0 FROM principals WHERE subject_id='local-cron-workload' AND organization_id='local-organization' AND tenant_id='local-tenant' ON CONFLICT DO NOTHING;
INSERT INTO role_bindings SELECT organization_id,tenant_id,project_id,agent_uid,'local-workflow-workload','developer' FROM role_bindings WHERE subject_id='local-cron-workload' AND organization_id='local-organization' AND tenant_id='local-tenant' ON CONFLICT DO NOTHING;
